            self.AddEquity("AAPL", Resolution.Daily).Symbol,
            self.AddEquity("IBM", Resolution.Daily).Symbol,
            self.AddEquity("BAC", Resolution.Daily).Symbol,
            self.AddEquity("AIG", Resolution.Daily).Symbol
        ]

        self.spy = self.Symbol("SPY")
        self.aapl = self.Symbol("AAPL")

        self.bars = {symbol: RollingWindow[TradeBar](201) for symbol in self.symbols}

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0
        self.aapl_red_streak = 0

    def OnData(self, data: Slice):
        for symbol in self.symbols:
            if data.Bars.ContainsKey(symbol):
                self.bars[symbol].Add(data.Bars[symbol])

        if any(not data.Bars.ContainsKey(symbol) for symbol in self.symbols):
            return

        if any(self.bars[symbol].Count < 201 for symbol in self.symbols):
            return

        spy_closes = [self.bars[self.spy][i].Close for i in range(201)]
        aapl_closes = [self.bars[self.aapl][i].Close for i in range(201)]

        spy_close = spy_closes[0]
        spy_previous_close = spy_closes[1]
        aapl_close = aapl_closes[0]
        aapl_previous_close = aapl_closes[1]

        sma_200_today = sum(spy_closes[0:200]) / 200.0
        sma_200_yesterday = sum(spy_closes[1:201]) / 200.0
        sma_50_today = sum(spy_closes[0:50]) / 50.0
        sma_50_yesterday = sum(spy_closes[1:51]) / 50.0

        rsi_14 = self.CalculateRsi(aapl_closes[0:15])

        if aapl_close < aapl_previous_close:
            self.aapl_red_streak += 1
        else:
            self.aapl_red_streak = 0

        if self.strategy_a_shares > 0:
            if spy_previous_close >= sma_50_yesterday and spy_close < sma_50_today:
                self.MarketOrder(self.spy, -self.strategy_a_shares)
                self.strategy_a_shares = 0

        if self.strategy_b_shares > 0:
            if rsi_14 > 60:
                self.MarketOrder(self.aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

        if self.strategy_a_shares == 0:
            if spy_previous_close <= sma_200_yesterday and spy_close > sma_200_today:
                quantity = int((self.Portfolio.TotalPortfolioValue * 0.40) / spy_close)
                if quantity > 0:
                    self.MarketOrder(self.spy, quantity)
                    self.strategy_a_shares = quantity

        if self.strategy_b_shares == 0:
            if self.aapl_red_streak >= 3 and self.Portfolio.Cash >= 20000:
                quantity = int(20000 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity)
                    self.strategy_b_shares = quantity

    def CalculateRsi(self, closes):
        gains = 0.0
        losses = 0.0

        for i in range(14):
            change = closes[i] - closes[i + 1]
            if change > 0:
                gains += change
            else:
                losses -= change

        average_gain = gains / 14.0
        average_loss = losses / 14.0

        if average_loss == 0:
            return 100.0

        rs = average_gain / average_loss
        return 100.0 - (100.0 / (1.0 + rs))
