class IndependentSpyAaplStrategies(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.spy = self.add_equity("SPY", Resolution.DAILY).symbol
        self.aapl = self.add_equity("AAPL", Resolution.DAILY).symbol
        self.ibm = self.add_equity("IBM", Resolution.DAILY).symbol
        self.bac = self.add_equity("BAC", Resolution.DAILY).symbol
        self.aig = self.add_equity("AIG", Resolution.DAILY).symbol
        self.symbols = [self.spy, self.aapl, self.ibm, self.bac, self.aig]

        self.closes = {symbol: RollingWindow[float](201) for symbol in self.symbols}
        self.aapl_rsi = RelativeStrengthIndex(14, MovingAverageType.WILDERS)

        self.strategy_a_shares = 0
        self.strategy_b_shares = 0

    def on_data(self, data: Slice):
        if any(symbol not in data.bars for symbol in self.symbols):
            return

        for symbol in self.symbols:
            self.closes[symbol].add(data.bars[symbol].close)

        self.aapl_rsi.update(
            IndicatorDataPoint(self.time, data.bars[self.aapl].close)
        )

        if not self._all_rules_ready():
            return

        # Sells are evaluated before buys.
        if self.strategy_a_shares > 0 and self._spy_sma50_crosses_below_sma200():
            self.market_order(self.spy, -self.strategy_a_shares)
            self.strategy_a_shares = 0

        if self.strategy_b_shares > 0 and self.aapl_rsi.current.value > 60:
            self.market_order(self.aapl, -self.strategy_b_shares)
            self.strategy_b_shares = 0

        if self.strategy_a_shares == 0 and self._spy_close_crosses_above_sma200():
            close = data.bars[self.spy].close
            shares = int((self.portfolio.total_portfolio_value * 0.40) // close)
            if shares > 0:
                self.market_order(self.spy, shares)
                self.strategy_a_shares = shares

        if self.strategy_b_shares == 0 and self._aapl_red_streak() >= 3:
            close = data.bars[self.aapl].close
            if self.portfolio.cash >= 20_000:
                shares = int(20_000 // close)
                if shares > 0:
                    self.market_order(self.aapl, shares)
                    self.strategy_b_shares = shares

    def _all_rules_ready(self):
        return (
            self.closes[self.spy].is_ready
            and self.closes[self.aapl].count >= 4
            and self.aapl_rsi.is_ready
        )

    def _sma(self, window, length, offset=0):
        return sum(window[i + offset] for i in range(length)) / length

    def _spy_close_crosses_above_sma200(self):
        window = self.closes[self.spy]
        today_close = window[0]
        yesterday_close = window[1]
        today_sma200 = self._sma(window, 200, 0)
        yesterday_sma200 = self._sma(window, 200, 1)

        return (
            yesterday_close <= yesterday_sma200
            and today_close > today_sma200
        )

    def _spy_sma50_crosses_below_sma200(self):
        window = self.closes[self.spy]
        today_sma50 = self._sma(window, 50, 0)
        yesterday_sma50 = self._sma(window, 50, 1)
        today_sma200 = self._sma(window, 200, 0)
        yesterday_sma200 = self._sma(window, 200, 1)

        return (
            yesterday_sma50 >= yesterday_sma200
            and today_sma50 < today_sma200
        )

    def _aapl_red_streak(self):
        window = self.closes[self.aapl]
        streak = 0

        for index in range(window.count - 1):
            if window[index] < window[index + 1]:
                streak += 1
            else:
                break

        return streak
