from collections import deque
from math import floor


class IndependentDailyStrategies(QCAlgorithm):

    def initialize(self):
        self.set_start_date(2006, 1, 3)
        self.set_end_date(2015, 12, 31)
        self.set_cash(1_000_000)

        self.tickers = ["SPY", "AAPL", "IBM", "BAC", "AIG"]
        self.symbols = {
            ticker: self.add_equity(ticker, Resolution.DAILY).symbol
            for ticker in self.tickers
        }

        self.spy_closes = deque(maxlen=201)
        self.aapl_closes = deque(maxlen=15)
        self.previous_closes = {}
        self.aapl_red_streak = 0

        self.aapl_rsi = self.rsi(
            self.symbols["AAPL"],
            14,
            MovingAverageType.WILDERS,
            Resolution.DAILY
        )

        self.strategy_a_lot = 0
        self.strategy_b_lot = 0

    def on_data(self, data: Slice):
        bars = {}

        for ticker, symbol in self.symbols.items():
            if not data.bars.contains_key(symbol):
                return
            bars[ticker] = data.bars[symbol]

        spy_bar = bars["SPY"]
        aapl_bar = bars["AAPL"]

        previous_aapl_close = self.previous_closes.get("AAPL")
        if previous_aapl_close is not None:
            if aapl_bar.close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        self.spy_closes.append(spy_bar.close)
        self.aapl_closes.append(aapl_bar.close)

        all_history_ready = (
            len(self.spy_closes) == 201
            and len(self.aapl_closes) == 15
            and self.aapl_rsi.is_ready
        )

        if not self.is_warming_up and all_history_ready:
            spy_values = list(self.spy_closes)
            current_sma_200 = sum(spy_values[-200:]) / 200.0
            previous_sma_200 = sum(spy_values[-201:-1]) / 200.0
            current_sma_50 = sum(spy_values[-50:]) / 50.0
            previous_sma_50 = sum(spy_values[-51:-1]) / 50.0

            spy_crosses_above_sma_200 = (
                spy_values[-2] <= previous_sma_200
                and spy_values[-1] > current_sma_200
            )

            spy_crosses_below_sma_50 = (
                spy_values[-2] >= previous_sma_50
                and spy_values[-1] < current_sma_50
            )

            if self.strategy_a_lot > 0 and spy_crosses_below_sma_50:
                self.market_order(self.symbols["SPY"], -self.strategy_a_lot)
                self.strategy_a_lot = 0

            if self.strategy_b_lot > 0 and self.aapl_rsi.current.value > 60:
                self.market_order(self.symbols["AAPL"], -self.strategy_b_lot)
                self.strategy_b_lot = 0

            if self.strategy_a_lot == 0 and spy_crosses_above_sma_200:
                target_value = self.portfolio.total_portfolio_value * 0.40
                quantity = floor(target_value / spy_bar.close)
                if quantity > 0:
                    self.market_order(self.symbols["SPY"], quantity)
                    self.strategy_a_lot = quantity

            if self.strategy_b_lot == 0 and self.aapl_red_streak >= 3:
                cash_amount = 20_000
                if self.portfolio.cash >= cash_amount:
                    quantity = floor(cash_amount / aapl_bar.close)
                    if quantity > 0:
                        self.market_order(self.symbols["AAPL"], quantity)
                        self.strategy_b_lot = quantity

        for ticker, bar in bars.items():
            self.previous_closes[ticker] = bar.close
