        closes = self.close_history[symbol]
        close = float(bar.Close)

        if ticker == "SPY":
            self.spy_close_previous = closes[-1] if len(closes) > 0 else None
            self.spy_sma50_previous = self._sma(closes, 50)
            self.spy_sma200_previous = self._sma(closes, 200)

        if ticker == "AAPL":
            self.aapl_close_previous = closes[-1] if len(closes) > 0 else None
            self._update_aapl_rsi(close)

        closes.append(close)

        if ticker == "SPY":
            self.spy_sma50 = self._sma(closes, 50)
            self.spy_sma200 = self._sma(closes, 200)

    def _update_aapl_rsi(self, close):
        prior_rsi = self.aapl_rsi
        prior_close = self.aapl_close_previous

        if prior_close is None:
            self.aapl_rsi_previous = prior_rsi
            return

        change = close - prior_close
        gain = max(change, 0.0)
        loss = max(-change, 0.0)

        if self.aapl_average_gain is None:
            self.aapl_rsi_seed_gains.append(gain)
            self.aapl_rsi_seed_losses.append(loss)

            if len(self.aapl_rsi_seed_gains) == 14:
                self.aapl_average_gain = sum(self.aapl_rsi_seed_gains) / 14.0
                self.aapl_average_loss = sum(self.aapl_rsi_seed_losses) / 14.0
                self.aapl_rsi = self._rsi_value(
                    self.aapl_average_gain,
                    self.aapl_average_loss
                )
        else:
            self.aapl_average_gain = (
                self.aapl_average_gain * 13.0 + gain
            ) / 14.0
            self.aapl_average_loss = (
                self.aapl_average_loss * 13.0 + loss
            ) / 14.0
            self.aapl_rsi = self._rsi_value(
                self.aapl_average_gain,
                self.aapl_average_loss
            )

        self.aapl_rsi_previous = prior_rsi

    def _all_required_history_ready(self):
        return (
            self.spy_sma50 is not None and
            self.spy_sma50_previous is not None and
            self.spy_sma200 is not None and
            self.spy_sma200_previous is not None and
            self.aapl_rsi is not None and
            self.aapl_rsi_previous is not None
        )

    def _aapl_has_three_consecutive_red_days(self):
        closes = self.close_history[self.symbols["AAPL"]]
        if len(closes) < 4:
            return False

        return (
            closes[-1] < closes[-2] and
            closes[-2] < closes[-3] and
            closes[-3] < closes[-4]
        )

    def _sma(self, values, period):
        if len(values) < period:
            return None
        return sum(list(values)[-period:]) / period

    def _rsi_value(self, average_gain, average_loss):
        if average_loss == 0:
            return 100.0
        if average_gain == 0:
            return 0.0
        rs = average_gain / average_loss
        return 100.0 - (100.0 / (1.0 + rs))
