        previous_aapl_close = self.previous_closes.get("AAPL")
        if previous_aapl_close is not None:
            if aapl_close < previous_aapl_close:
                self.aapl_red_streak += 1
            else:
                self.aapl_red_streak = 0

        indicators_ready = (
            self.spy_sma_200.IsReady
            and self.spy_sma_50.IsReady
            and self.aapl_rsi_14.IsReady
            and self.previous_spy_sma_200 is not None
            and self.previous_spy_sma_50 is not None
            and "SPY" in self.previous_closes
            and "AAPL" in self.previous_closes
        )

        if indicators_ready:
            previous_spy_close = self.previous_closes["SPY"]
            spy_sma_200 = self.spy_sma_200.Current.Value
            spy_sma_50 = self.spy_sma_50.Current.Value

            # Sells before buys.
            if self.strategy_a_shares > 0:
                close_crosses_below_sma_50 = (
                    previous_spy_close >= self.previous_spy_sma_50
                    and spy_close < spy_sma_50
                )
                if close_crosses_below_sma_50:
                    self.MarketOrder(self.spy, -self.strategy_a_shares)
                    self.strategy_a_shares = 0

            if self.strategy_b_shares > 0 and self.aapl_rsi_14.Current.Value > 60:
                self.MarketOrder(self.aapl, -self.strategy_b_shares)
                self.strategy_b_shares = 0

            if self.strategy_a_shares == 0:
                close_crosses_above_sma_200 = (
                    previous_spy_close <= self.previous_spy_sma_200
                    and spy_close > spy_sma_200
                )
                if close_crosses_above_sma_200:
                    target_value = 0.40 * self.Portfolio.TotalPortfolioValue
                    quantity = int(target_value // spy_close)
                    if quantity > 0:
                        self.MarketOrder(self.spy, quantity)
                        self.strategy_a_shares = quantity

            if self.strategy_b_shares == 0 and self.aapl_red_streak >= 3:
                if self.Portfolio.Cash >= 20000:
                    quantity = int(20000 // aapl_close)
                    if quantity > 0:
                        self.MarketOrder(self.aapl, quantity)
                        self.strategy_b_shares = quantity

        self.previous_spy_sma_200 = self.spy_sma_200.Current.Value if self.spy_sma_200.IsReady else None
        self.previous_spy_sma_50 = self.spy_sma_50.Current.Value if self.spy_sma_50.IsReady else None

        for ticker, bar in bars.items():
            self.previous_closes[ticker] = bar.Close
